#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_palette;
uniform float amzp_alpha;
layout(color) uniform half4 amzp_color1;
layout(color) uniform half4 amzp_color2;
layout(color) uniform half4 amzp_color3;
layout(color) uniform half4 amzp_color4;
layout(color) uniform half4 amzp_color5;
layout(color) uniform half4 amzp_color6;
layout(color) uniform half4 amzp_color7;
layout(color) uniform half4 amzp_color8;
uniform float amzp_shades;
        void amzRender() {
            float4 texColor = amzTexture(0,amzScreenNorm());
            float a = texColor.a;
            float3 rgb = texColor.rgb / max(0.0001,a);
            float3 c[16];
            int ncolors;
            if( int(amzp_palette) == 0 ) {
                c[0] = float3(0.000, 0.000, 0.000);
                c[1] = float3(0.333, 1.000, 0.333);
                c[2] = float3(1.000, 0.333, 0.333);
                c[3] = float3(1.000, 1.000, 0.333);
                ncolors = 4;
            } else if( int(amzp_palette) == 1 ) {
                c[0] = float3(0.000, 0.000, 0.000);
                c[1] = float3(0.333, 1.000, 1.000);
                c[2] = float3(1.000, 0.333, 1.000);
                c[3] = float3(1.000, 1.000, 1.000);
                ncolors = 4;
            } else if( int(amzp_palette) == 10 ) {
                c[0] = float3(0.333, 0.333, 1.000);
                c[1] = float3(0.333, 1.000, 1.000);
                c[2] = float3(1.000, 0.333, 1.000);
                c[3] = float3(1.000, 1.000, 1.000);
                ncolors = 4;
            } else if( int(amzp_palette) == 2 ) {
                c[0] = float3(0.000, 0.000, 0.000);
                c[1] = float3(0.000, 0.000, 0.667);
                c[2] = float3(0.000, 0.667, 0.000);
                c[3] = float3(0.000, 0.667, 0.667);
                c[4] = float3(0.667, 0.000, 0.000);
                c[5] = float3(0.667, 0.000, 0.667);
                c[6] = float3(0.667, 0.333, 0.000);
                c[7] = float3(0.667, 0.667, 0.667);
                c[8] = float3(0.333, 0.333, 0.333);
                c[9] = float3(0.333, 0.333, 1.000);
                c[10] = float3(0.333, 1.000, 0.333);
                c[11] = float3(0.333, 1.000, 1.000);
                c[12] = float3(1.000, 0.333, 0.333);
                c[13] = float3(1.000, 0.333, 1.000);
                c[14] = float3(1.000, 1.000, 0.333);
                c[15] = float3(1.000, 1.000, 1.000);
                ncolors = 16;
            } else if( int(amzp_palette) == 3 ) {
                c[0] = float3(0.000, 0.000, 0.000);
                c[1] = float3(0.000, 0.000, 0.667);
                c[2] = float3(0.000, 0.667, 0.000);
                c[3] = float3(0.333, 0.667, 1.000);
                c[4] = float3(0.667, 0.000, 0.000);
                c[5] = float3(0.667, 0.000, 0.667);
                c[6] = float3(0.333, 0.667, 0.000);
                c[7] = float3(0.667, 0.667, 0.667);
                c[8] = float3(0.333, 0.333, 0.333);
                c[9] = float3(0.333, 0.333, 1.000);
                c[10] = float3(0.333, 1.000, 0.333);
                c[11] = float3(0.333, 1.000, 1.000);
                c[12] = float3(1.000, 0.333, 0.333);
                c[13] = float3(1.000, 0.333, 1.000);
                c[14] = float3(1.000, 1.000, 0.333);
                c[15] = float3(1.000, 1.000, 1.000);
                ncolors = 16;
            } else if( int(amzp_palette) == 4 ) {
                c[0] = float3(0.000, 0.000, 0.000);
                c[1] = float3(0.333, 0.333, 1.000);
                c[2] = float3(0.333, 1.000, 0.333);
                c[3] = float3(0.333, 1.000, 1.000);
                c[4] = float3(1.000, 0.333, 0.333);
                c[5] = float3(1.000, 0.333, 1.000);
                c[6] = float3(1.000, 1.000, 0.333);
                c[7] = float3(1.000, 1.000, 1.000);
                ncolors = 8;
            } else if( int(amzp_palette) == 5 ) {
                c[0] = float3(0.000, 0.000, 0.000);
                c[1] = float3(0.333, 0.333, 0.333);
                c[2] = float3(0.667, 0.667, 0.667);
                c[3] = float3(1.000, 1.000, 1.000);
                ncolors = 4;
            } else if( int(amzp_palette) == 6 && (amzp_shades>0.5)) {
                c[0] = amzp_color1.rgb;
                c[1] = amzp_color2.rgb;
                c[2] = amzp_color3.rgb;
                c[4] = amzp_color1.rgb * 0.667;
                c[5] = amzp_color2.rgb * 0.667;
                c[6] = amzp_color3.rgb * 0.667;
                ncolors = 6;
            } else if( int(amzp_palette) == 6 ) {
                c[0] = amzp_color1.rgb;
                c[1] = amzp_color2.rgb;
                c[2] = amzp_color3.rgb;
                ncolors = 3;
            } else if( int(amzp_palette) == 7 && (amzp_shades>0.5) ) {
                c[0] = amzp_color1.rgb;
                c[1] = amzp_color2.rgb;
                c[2] = amzp_color3.rgb;
                c[3] = amzp_color4.rgb;
                c[4] = amzp_color1.rgb * 0.667;
                c[5] = amzp_color2.rgb * 0.667;
                c[6] = amzp_color3.rgb * 0.667;
                c[7] = amzp_color4.rgb * 0.667;
                ncolors = 8;
            } else if( int(amzp_palette) == 7 ) {
                c[0] = amzp_color1.rgb;
                c[1] = amzp_color2.rgb;
                c[2] = amzp_color3.rgb;
                c[3] = amzp_color4.rgb;
                ncolors = 4;
            } else if( int(amzp_palette) == 8 && (amzp_shades>0.5) ) {
                c[0] = amzp_color1.rgb;
                c[1] = amzp_color2.rgb;
                c[2] = amzp_color3.rgb;
                c[3] = amzp_color4.rgb;
                c[4] = amzp_color5.rgb;
                c[5] = amzp_color6.rgb;
                c[6] = amzp_color1.rgb * 0.667;
                c[7] = amzp_color2.rgb * 0.667;
                c[8] = amzp_color3.rgb * 0.667;
                c[9] = amzp_color4.rgb * 0.667;
                c[10] = amzp_color5.rgb * 0.667;
                c[11] = amzp_color6.rgb * 0.667;
                ncolors = 12;
            } else if( int(amzp_palette) == 8 ) {
                c[0] = amzp_color1.rgb;
                c[1] = amzp_color2.rgb;
                c[2] = amzp_color3.rgb;
                c[3] = amzp_color4.rgb;
                c[4] = amzp_color5.rgb;
                c[5] = amzp_color6.rgb;
                ncolors = 6;
            } else if( int(amzp_palette) == 9 && (amzp_shades>0.5) ) {
                c[0] = amzp_color1.rgb;
                c[1] = amzp_color2.rgb;
                c[2] = amzp_color3.rgb;
                c[3] = amzp_color4.rgb;
                c[4] = amzp_color5.rgb;
                c[5] = amzp_color6.rgb;
                c[6] = amzp_color7.rgb;
                c[7] = amzp_color8.rgb;
                c[8] = amzp_color1.rgb * 0.667;
                c[9] = amzp_color2.rgb * 0.667;
                c[10] = amzp_color3.rgb * 0.667;
                c[11] = amzp_color4.rgb * 0.667;
                c[12] = amzp_color5.rgb * 0.667;
                c[13] = amzp_color6.rgb * 0.667;
                c[14] = amzp_color7.rgb * 0.667;
                c[15] = amzp_color8.rgb * 0.667;
                ncolors = 16;
            } else if( int(amzp_palette) == 9 ) {
                c[0] = amzp_color1.rgb;
                c[1] = amzp_color2.rgb;
                c[2] = amzp_color3.rgb;
                c[3] = amzp_color4.rgb;
                c[4] = amzp_color5.rgb;
                c[5] = amzp_color6.rgb;
                c[6] = amzp_color7.rgb;
                c[7] = amzp_color8.rgb;
                ncolors = 8;
            }
            float3 bestColor = c[0];
            float bestDist = 100.0;
            for( int i=0; i<ncolors; i++ ) {
                float l = length(c[i] - rgb);
                if( l < bestDist ) {
                    bestDist = l;
                    bestColor = c[i];
                }
            }
            amzOutput = mix(texColor, float4(bestColor,1.0) * a, amzp_alpha);
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
